args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?filmYoung ?filmYoungLabel ?dirYoung ?dirYoungLabel ?bYoung ?filmOld ?filmOldLabel ?dirOld ?dirOldLabel ?bOld WHERE {
  VALUES (?f1 ?f2) { (dbr:Phalitamsha dbr:Gladiators_Seven) }
  ?f1 dbo:director ?d1 .
  ?f2 dbo:director ?d2 .
  OPTIONAL { ?d1 dbo:birthDate ?b1. }
  OPTIONAL { ?d1 dbp:birth_date ?b1_2. }
  OPTIONAL { ?d2 dbo:birthDate ?b2. }
  OPTIONAL { ?d2 dbp:birth_date ?b2_2. }
  BIND(COALESCE(?b1, ?b1_2) AS ?bd1)
  BIND(COALESCE(?b2, ?b2_2) AS ?bd2)
  {
    FILTER(bound(?bd1) && bound(?bd2) && xsd:date(?bd1) > xsd:date(?bd2))
    BIND(?f1 AS ?filmYoung) BIND(?d1 AS ?dirYoung) BIND(?bd1 AS ?bYoung)
    BIND(?f2 AS ?filmOld) BIND(?d2 AS ?dirOld) BIND(?bd2 AS ?bOld)
  } UNION {
    FILTER(bound(?bd1) && bound(?bd2) && xsd:date(?bd2) > xsd:date(?bd1))
    BIND(?f2 AS ?filmYoung) BIND(?d2 AS ?dirYoung) BIND(?bd2 AS ?bYoung)
    BIND(?f1 AS ?filmOld) BIND(?d1 AS ?dirOld) BIND(?bd1 AS ?bOld)
  }
  OPTIONAL { ?filmYoung rdfs:label ?filmYoungLabel. FILTER(lang(?filmYoungLabel)='en') }
  OPTIONAL { ?filmOld rdfs:label ?filmOldLabel. FILTER(lang(?filmOldLabel)='en') }
  OPTIONAL { ?dirYoung rdfs:label ?dirYoungLabel. FILTER(lang(?dirYoungLabel)='en') }
  OPTIONAL { ?dirOld rdfs:label ?dirOldLabel. FILTER(lang(?dirOldLabel)='en') }
}
LIMIT 10

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?bd WHERE {
  VALUES (?film ?director) { (dbr:Phalitamsha dbr:Puttanna_Kanagal) (dbr:Gladiators_Seven dbr:Alberto_De_Martino) }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel)='en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel)='en') }
  OPTIONAL { ?director dbo:birthDate ?bd. }
}
ORDER BY DESC(xsd:date(?bd))
LIMIT 1

